        # Target end positions for more aggressive changes
        for i in range(max(0, len(mutated) - 15), len(mutated)):
            if random.random() < 0.3:  # Higher probability
                mutated[i] *= random.uniform(0.4, 1.8)

        # 3. Try swapping nearby values to potentially reduce convolution peak
        if len(mutated) > 10 and random.random() < 0.3:  # Increased probability
            idx1, idx2 = random.sample(range(len(mutated)), 2)
            mutated[idx1], mutated[idx2] = mutated[idx2], mutated[idx1]

        # 4. Try adding a small amount of noise to encourage escape from local optima
        if random.random() < 0.25:
            for i in range(len(mutated)):
                if random.random() < 0.25:  # Higher probability
                    mutated[i] += random.uniform(-1.0, 1.0)

        # 5. Try to balance the sequence to avoid extreme values
        if random.random() < 0.25:
            # Apply a soft normalization to keep values balanced
            total = sum(mutated)
            if total > 0:
                avg = total / len(mutated)
                for i in range(len(mutated)):
                    # Adjust toward average but with some randomness
                    if mutated[i] > avg * 1.7:
                        mutated[i] *= random.uniform(0.8, 1.05)
                    elif mutated[i] < avg * 0.3:
                        mutated[i] *= random.uniform(1.0, 1.2)

