        if random.random() < 0.2:
            # Apply a more sophisticated smoothing operation with variable window
            smoothed = []
            window_size = random.choice([3, 5, 7, 9])  # Include larger windows
            for i in range(len(mutated)):
                if i < window_size//2 or i >= len(mutated) - window_size//2:
                    smoothed.append(mutated[i])
                else:
                    # Moving average with variable window
                    start = max(0, i - window_size//2)
                    end = min(len(mutated), i + window_size//2 + 1)
                    avg_val = sum(mutated[start:end]) / (end - start)
                    smoothed.append(avg_val)
            mutated = smoothed

        # 7. Add a specialized technique: peak reduction with more aggressive scaling
        if random.random() < 0.2:
            # Reduce peaks by applying a scaling factor to high-value positions
            max_val = max(mutated)
            if max_val > 0:
                threshold = max_val * 0.7
                for i in range(len(mutated)):
                    if mutated[i] > threshold:
                        mutated[i] *= random.uniform(0.65, 0.92)

        # 8. Add a new technique: harmonic balancing for better distribution
        if random.random() < 0.15:
            # Try to create a more evenly distributed sequence
            total = sum(mutated)
            if total > 0:
                target_avg = total / len(mutated)
                for i in range(len(mutated)):
                    # Adjust toward target average with some randomness
                    if mutated[i] > target_avg * 1.5:
                        mutated[i] *= random.uniform(0.85, 0.95)
                    elif mutated[i] < target_avg * 0.5:
                        mutated[i] *= random.uniform(1.05, 1.15)

        # 9. Add a technique to reduce correlations between adjacent elements
        if random.random() < 0.1:
            # Apply a small amount of decorrelation
            for i in range(1, len(mutated)-1):
                if mutated[i] > mutated[i-1] and mutated[i] > mutated[i+1]:
                    # Reduce local maximum
