        mutated = [min(1000, x) for x in mutated]  # Ensure bounded values

        fitness = evaluate_fitness(mutated)
        if fitness > best_fitness:
            best_fitness = fitness
            current_seq = mutated
            recent_improvements.append(fitness)

            # Keep track of recent improvements for adaptive behavior
            if len(recent_improvements) > 10:
                recent_improvements.pop(0)

    return current_seq
