    best_sequence_so_far = None

    # Evolution loop with adaptive parameters
    for generation in range(60):  # More generations for better convergence
        # Evaluate fitness of population
        fitness_scores = [evaluate_fitness(seq) for seq in population]

        # Update global best
        max_fitness_idx = np.argmax(fitness_scores)
        if fitness_scores[max_fitness_idx] > best_fitness_so_far:
            best_fitness_so_far = fitness_scores[max_fitness_idx]
            best_sequence_so_far = population[max_fitness_idx].copy()

        # Select top performers (tournament selection)
        tournament_size = 12  # Larger tournament for stronger selection pressure
        selected_indices = []
        for _ in range(population_size // 2):
            tournament = random.sample(range(population_size), tournament_size)
            winner = max(tournament, key=lambda i: fitness_scores[i])
            selected_indices.append(winner)

        top_population = [population[i] for i in selected_indices]

        # Create new population through advanced crossover and mutation
        new_population = top_population.copy()

        # Add offspring
        while len(new_population) < population_size:
            parent1 = random.choice(top_population)
